def transform(grid):
    # Tile grid into 3x3 blocks and take the predominant non-background color per block.
    out=[]
    for br in range(4):
        row=[]
        for bc in range(4):
            block=[grid[r][c] for r in range(br*3,(br+1)*3) for c in range(bc*3,(bc+1)*3)]
            counts={x:block.count(x) for x in set(block) if x != 5}
            row.append(max(counts,key=counts.get) if counts else 5)
        out.append(row)
    return out
